{
  "name": "SSH远程客户端",
  "name_en": "SSH Remote Client",
  "manufacturer": "",
  "description": "一个非实体的软件组件，用于在实验系统中通过 SSH 和 SFTP 与远程主机通信。它可获取连接与传输会话、上传和下载文件、启动远程命令，并读取命令通道输出，常用于实验控制计算机、远程节点或数据处理主机之间的自动化交互。",
  "description_en": "A non-physical software component for communicating with remote hosts over SSH and SFTP in laboratory systems. It can obtain connection and transport sessions, upload and download files, start remote commands, and read command-channel output, commonly used for automation between experiment controllers, remote nodes, and data-processing hosts.",
  "actions": [
    {
      "action_name": "auto-get_ssh",
      "description": "获取 SSH 连接对象。",
      "description_en": "Get the SSH connection object."
    },
    {
      "action_name": "auto-get_transport",
      "description": "获取 SSH 传输层会话对象。",
      "description_en": "Get the SSH transport session object."
    },
    {
      "action_name": "auto-get_sftp",
      "description": "获取 SFTP 会话对象。",
      "description_en": "Get the SFTP session object."
    },
    {
      "action_name": "auto-upload",
      "description": "上传文件到远程主机，并通过临时文件后原子替换方式降低竞争条件风险。",
      "description_en": "Upload a file to the remote host, using a temporary file and atomic replacement to reduce race-condition risk."
    },
    {
      "action_name": "auto-prepare_download",
      "description": "准备远程文件下载。",
      "description_en": "Prepare a remote file for download."
    },
    {
      "action_name": "auto-download",
      "description": "下载已准备好的远程文件。",
      "description_en": "Download the prepared remote file."
    },
    {
      "action_name": "auto-spawn_command",
      "description": "在远程主机上启动命令，可选择通过登录 shell 和伪终端运行。",
      "description_en": "Spawn a command on the remote host, optionally using a login shell and pseudo-terminal."
    },
    {
      "action_name": "auto-drain",
      "description": "读取并清空通信通道中的输出数据。",
      "description_en": "Read and drain output data from a communication channel."
    },
    {
      "action_name": "auto-run_command",
      "description": "执行远程命令并处理其运行结果。",
      "description_en": "Run a remote command and handle its execution result."
    }
  ],
  "tag_hints": [
    "SSH remote execution",
    "SFTP file transfer",
    "remote experiment control",
    "command channel handling",
    "upload/download automation",
    "login shell execution"
  ]
}

